  1→import { test, expect, Browser, Page } from '@playwright/test';
  2→import { generatePrivateKey, privateKeyToAccount, type PrivateKeyAccount } from 'viem/accounts';
  3→import { loginViaWallet, createWalletContext } from '../utils/wallet-login-helpers';
  4→import { FileListPage } from '../page-objects/file-browser/file-list.page';
  5→import { UploadZonePage } from '../page-objects/file-browser/upload-zone.page';
  6→import { ContextMenuPage } from '../page-objects/file-browser/context-menu.page';
  7→import { BreadcrumbsPage } from '../page-objects/file-browser/breadcrumbs.page';
  8→import { SelectionActionBarPage } from '../page-objects/file-browser/selection-action-bar.page';
  9→import { CreateFolderDialogPage } from '../page-objects/dialogs/create-folder-dialog.page';
 10→import { RenameDialogPage } from '../page-objects/dialogs/rename-dialog.page';
 11→import { ConfirmDialogPage } from '../page-objects/dialogs/confirm-dialog.page';
 12→import { MoveDialogPage } from '../page-objects/dialogs/move-dialog.page';
 13→import { createTestTextFile, createTestBinaryFile, cleanupTestFiles } from '../utils/test-files';
 14→
 15→/**
 16→ * Load Test — Concurrent Users Against Staging
 17→ *
 18→ * Each client gets a unique wallet (keypair) injected via EIP-6963 mock provider.
 19→ * Full auth flow: wallet → SIWE sign → Core Kit → key reconstruction → vault init.
 20→ * Then drives ~50+ file operations that each trigger IPNS publishes.
 21→ *
 22→ * Usage:
 23→ *   cd tests/e2e
 24→ *   pnpm exec playwright test tests/load-test.spec.ts --config=playwright.load.config.ts
 25→ *
 26→ * Env vars:
 27→ *   LOAD_TEST_CLIENTS=5   Number of concurrent clients (default: 3)
 28→ */
 29→
 30→const NUM_CLIENTS = parseInt(process.env.LOAD_TEST_CLIENTS ?? '5', 10);
 31→
 32→// Generous timeouts — multiple clients hitting staging concurrently
 33→test.setTimeout(600_000); // 10 minutes
 34→
 35→interface LoadClient {
 36→  id: number;
 37→  account: PrivateKeyAccount;
 38→  page: Page;
 39→  context: Awaited<ReturnType<Browser['newContext']>>;
 40→  fileList: FileListPage;
 41→  uploadZone: UploadZonePage;
 42→  contextMenu: ContextMenuPage;
 43→  breadcrumbs: BreadcrumbsPage;
 44→  selectionBar: SelectionActionBarPage;
 45→  createFolderDialog: CreateFolderDialogPage;
 46→  renameDialog: RenameDialogPage;
 47→  confirmDialog: ConfirmDialogPage;
 48→  moveDialog: MoveDialogPage;
 49→}
 50→
 51→// Operation timeout — each individual UI action
 52→const OP_TIMEOUT = 30_000;
 53→
 54→// ─── Helpers ───────────────────────────────────────────────────────────────
 55→
 56→/**
 57→ * Recover page to a known state: dismiss any open modals/menus, navigate to root.
 58→ * Called after a failed op to prevent cascading failures.
 59→ */
 60→async function resetState(client: LoadClient): Promise<void> {
 61→  try {
 62→    // Press Escape a few times to dismiss modals/menus/dialogs
 63→    for (let i = 0; i < 3; i++) {
 64→      await client.page.keyboard.press('Escape');
 65→      await client.page.waitForTimeout(200);
 66→    }
 67→    // Click on an empty area to deselect
 68→    await client.page.mouse.click(0, 0);
 69→    await client.page.waitForTimeout(300);
 70→    // Navigate to root if breadcrumbs are visible
 71→    const breadcrumbVisible = await client.breadcrumbs
 72→      .container()
 73→      .isVisible()
 74→      .catch(() => false);
 75→    if (breadcrumbVisible) {
 76→      await client.breadcrumbs.clickBreadcrumb('my vault').catch(() => {});
 77→      await client.page.waitForTimeout(1000);
 78→    }
 79→  } catch {
 80→    // Best-effort reset — if the page is completely broken, subsequent ops will also fail
 81→  }
 82→}
 83→
 84→/** Safe wrapper for operations — logs failures but doesn't abort the run */
 85→async function op(
 86→  client: LoadClient,
 87→  description: string,
 88→  fn: () => Promise<void>
 89→): Promise<boolean> {
 90→  try {
 91→    await fn();
 92→    console.log(`    [C${client.id}] ✓ ${description}`);
 93→    return true;
 94→  } catch (err) {
 95→    console.warn(`    [C${client.id}] ✗ ${description}: ${(err as Error).message.slice(0, 120)}`);
 96→    await resetState(client);
 97→    return false;
 98→  }
 99→}
100→
101→/** Navigate to root via breadcrumbs */
102→async function goToRoot(client: LoadClient): Promise<void> {
103→  await client.breadcrumbs.clickBreadcrumb('my vault');
104→  await client.page.waitForTimeout(1000);
105→}
106→
107→/** Navigate into a subfolder */
108→async function enterFolder(client: LoadClient, folderName: string): Promise<void> {
109→  await client.fileList.doubleClickFolder(folderName);
110→  await client.breadcrumbs.waitForPathToContain(folderName, { timeout: OP_TIMEOUT });
111→}
112→
113→/** Create a folder via the UI */
114→async function createFolder(client: LoadClient, name: string): Promise<void> {
115→  // Ensure the new folder button is ready
116→  await client.page
117→    .locator('.file-browser-new-folder-button')
118→    .waitFor({ state: 'visible', timeout: 10_000 });
119→  await client.page.locator('.file-browser-new-folder-button').click();
120→  await client.createFolderDialog.waitForOpen({ timeout: 5000 });
121→  await client.createFolderDialog.createFolder(name);
122→  await client.fileList.waitForItemToAppear(name, { timeout: OP_TIMEOUT });
123→}
124→
125→/** Upload a file and wait for it to appear */
126→async function uploadFile(client: LoadClient, filePath: string, fileName: string): Promise<void> {
127→  await client.uploadZone.uploadFile(filePath);
128→  await client.uploadZone.waitForUploadComplete({ timeout: OP_TIMEOUT });
129→  await client.fileList.waitForItemToAppear(fileName, { timeout: OP_TIMEOUT });
130→}
131→
132→/** Right-click → Rename */
133→async function renameItem(client: LoadClient, oldName: string, newName: string): Promise<void> {
134→  await client.fileList.rightClickItem(oldName);
135→  await client.contextMenu.waitForOpen({ timeout: 5000 });
136→  await client.contextMenu.clickRename();
137→  await client.renameDialog.waitForOpen({ timeout: 5000 });
138→  await client.renameDialog.rename(newName);
139→  await client.fileList.waitForItemToAppear(newName, { timeout: OP_TIMEOUT });
140→}
141→
142→/** Right-click → Move to folder */
143→async function moveItem(client: LoadClient, itemName: string, destFolder: string): Promise<void> {
144→  await client.fileList.rightClickItem(itemName);
145→  await client.contextMenu.waitForOpen({ timeout: 5000 });
146→  await client.contextMenu.clickMove();
147→  await client.moveDialog.waitForOpen({ timeout: 5000 });
148→  // Use .first() to avoid strict mode violation when folder names are substrings
149→  // of other folder names (e.g., "c1-data" matching both "c1-data" and "c1-data-sub")
150→  await client.moveDialog.getFolderItem(destFolder).first().click();
151→  await client.moveDialog.clickMove();
152→  await client.moveDialog.waitForClose();
153→  await client.fileList.waitForItemToDisappear(itemName, { timeout: OP_TIMEOUT });
154→}
155→
156→/** Right-click → Delete (with confirm) */
157→async function deleteItem(client: LoadClient, itemName: string): Promise<void> {
158→  await client.fileList.rightClickItem(itemName);
159→  await client.contextMenu.waitForOpen({ timeout: 5000 });
160→  await client.contextMenu.clickDelete();
161→  await client.confirmDialog.waitForOpen({ timeout: 5000 });
162→  await client.confirmDialog.clickConfirm();
163→  await client.fileList.waitForItemToDisappear(itemName, { timeout: OP_TIMEOUT });
164→}
165→
166→/** Delete account by calling the API from within the page context.
167→ *  Uses fetch with credentials to send the refresh token cookie,
168→ *  gets a fresh access token, then calls DELETE /auth/account. */
169→async function deleteAccount(client: LoadClient): Promise<void> {
170→  // Discover the API base URL from the app's runtime config
171→  const apiBase = await client.page.evaluate(() => {
172→    // Vite injects env vars at build time — read from the same source as apiClient
173→    return (
174→      (window as Record<string, string>).__VITE_API_URL ||
175→      document.querySelector('meta[name="api-url"]')?.getAttribute('content') ||
176→      'https://api-staging.cipherbox.cc'
177→    );
178→  });
179→
180→  const deleted = await client.page.evaluate(async (apiUrl: string) => {
181→    // Step 1: Refresh to get a fresh access token (uses HTTP-only cookie)
182→    const refreshRes = await fetch(`${apiUrl}/auth/refresh`, {
183→      method: 'POST',
184→      credentials: 'include',
185→    });
186→    if (!refreshRes.ok) return { ok: false, step: 'refresh', status: refreshRes.status };
187→    const { accessToken } = await refreshRes.json();
188→
189→    // Step 2: Delete the account
190→    const deleteRes = await fetch(`${apiUrl}/auth/account`, {
191→      method: 'DELETE',
192→      credentials: 'include',
193→      headers: {
194→        Authorization: `Bearer ${accessToken}`,
195→        'Content-Type': 'application/json',
196→      },
197→      body: JSON.stringify({ confirmation: 'DELETE' }),
198→    });
199→    return { ok: deleteRes.ok, step: 'delete', status: deleteRes.status };
200→  }, apiBase);
201→
202→  if (!deleted.ok) {
203→    throw new Error(`Account deletion failed at ${deleted.step}: HTTP ${deleted.status}`);
204→  }
205→}
206→
207→/** Multi-select items and batch move */
208→async function batchMove(
209→  client: LoadClient,
210→  itemNames: string[],
211→  destFolder: string
212→): Promise<void> {
213→  // Select first item normally, then Ctrl+click the rest
214→  await client.fileList.selectItem(itemNames[0]);
215→  for (let i = 1; i < itemNames.length; i++) {
216→    await client.fileList.ctrlClickItem(itemNames[i]);
217→  }
218→  await client.selectionBar.waitForVisible({ timeout: 5000 });
219→  await client.selectionBar.clickMove();
220→  await client.moveDialog.waitForOpen({ timeout: 5000 });
221→  await client.moveDialog.getFolderItem(destFolder).first().click();
222→  await client.moveDialog.clickMove();
223→  await client.moveDialog.waitForClose();
224→  // Wait for all items to disappear from current view
225→  for (const name of itemNames) {
226→    await client.fileList.waitForItemToDisappear(name, { timeout: OP_TIMEOUT });
227→  }
228→}
229→
230→/** Multi-select items and batch delete */
231→async function batchDelete(client: LoadClient, itemNames: string[]): Promise<void> {
232→  await client.fileList.selectItem(itemNames[0]);
233→  for (let i = 1; i < itemNames.length; i++) {
234→    await client.fileList.ctrlClickItem(itemNames[i]);
235→  }
236→  await client.selectionBar.waitForVisible({ timeout: 5000 });
237→  await client.selectionBar.clickDelete();
238→  await client.confirmDialog.waitForOpen({ timeout: 5000 });
239→  await client.confirmDialog.clickConfirm();
240→  for (const name of itemNames) {
241→    await client.fileList.waitForItemToDisappear(name, { timeout: OP_TIMEOUT });
242→  }
243→}
244→
245→// ─── Main client workload ──────────────────────────────────────────────────
246→
247→/**
248→ * Full workload for a single client. ~50+ operations, each triggering IPNS publish.
249→ *
250→ * Structure:
251→ *   Phase 1: Create folder hierarchy (5 folders + 2 subfolders)     →  7 publishes
252→ *   Phase 2: Upload small text files (15 files across folders)      → 15 publishes
253→ *   Phase 3: Upload medium binary files (10 files)                  → 10 publishes
254→ *   Phase 4: Upload large binary files (5 files, 100KB–500KB)       →  5 publishes
255→ *   Phase 5: Edit text files (5 edits)                              →  5 publishes
256→ *   Phase 6: Rename items (8 renames: files + folders)              →  8 publishes
257→ *   Phase 7: Move items between folders (6 individual moves)        →  6 publishes
258→ *   Phase 8: Batch move (2 batches of 3 files)                      →  2 publishes
259→ *   Phase 9: Batch delete (2 batches of 3–4 files)                  →  2 publishes
260→ *   Phase 10: Individual deletes + cleanup (remaining items)        → ~10 publishes
261→ *                                                             Total: ~70 publishes
262→ */
263→async function runClientWorkload(
264→  client: LoadClient
265→): Promise<{ succeeded: number; failed: number }> {
266→  const { id } = client;
267→  const prefix = `c${id}`;
268→  let succeeded = 0;
269→  let failed = 0;
270→
271→  const count = (ok: boolean) => {
272→    if (ok) succeeded++;
273→    else failed++;
274→  };
275→
276→  // ─── Warm-up: first mutation after login races with initial sync polling.
277→  // Create and delete a dummy folder to let the sync settle.
278→  await op(client, 'Warm-up folder', async () => {
279→    await createFolder(client, `${prefix}-warmup`);
280→    await deleteItem(client, `${prefix}-warmup`);
281→  });
282→
283→  // ─── Phase 1: Create folder hierarchy ────────────────────────────────
284→  console.log(`  [C${id}] Phase 1: Creating folder hierarchy...`);
285→
286→  const folders = ['docs', 'images', 'data', 'archive', 'temp'];
287→  const folderNames = folders.map((f) => `${prefix}-${f}`);
288→
289→  for (const name of folderNames) {
290→    count(await op(client, `Create folder ${name}`, () => createFolder(client, name)));
291→  }
292→
293→  // Create subfolders inside 'docs' and 'data'
294→  const subfolders = [
295→    { parent: folderNames[0], name: `${prefix}-docs-sub` },
296→    { parent: folderNames[2], name: `${prefix}-data-sub` },
297→  ];
298→  for (const sub of subfolders) {
299→    count(
300→      await op(client, `Create subfolder ${sub.name}`, async () => {
301→        await enterFolder(client, sub.parent);
302→        await createFolder(client, sub.name);
303→        await goToRoot(client);
304→      })
305→    );
306→  }
307→
308→  // ─── Phase 2: Upload small text files ────────────────────────────────
309→  console.log(`  [C${id}] Phase 2: Uploading 15 small text files...`);
310→
311→  const textFiles: { name: string; path: string; folder: string | null }[] = [];
312→  // 5 files at root
313→  for (let i = 1; i <= 5; i++) {
314→    const f = createTestTextFile(
315→      `${prefix}-note-${i}.txt`,
316→      `Client ${id} note ${i}. Timestamp: ${Date.now()}. ${'Lorem ipsum dolor sit amet. '.repeat(10)}`
317→    );
318→    textFiles.push({ name: f.name, path: f.path, folder: null });
319→  }
320→  // 5 files in docs folder
321→  for (let i = 1; i <= 5; i++) {
322→    const f = createTestTextFile(
323→      `${prefix}-doc-${i}.txt`,
324→      `Document ${i} from client ${id}. ${'Content block. '.repeat(20)}`
325→    );
326→    textFiles.push({ name: f.name, path: f.path, folder: folderNames[0] });
327→  }
328→  // 5 files in data folder
329→  for (let i = 1; i <= 5; i++) {
330→    const f = createTestTextFile(
331→      `${prefix}-log-${i}.txt`,
332→      `Log entry ${i}: ${new Date().toISOString()} client=${id} ${'data '.repeat(50)}`
333→    );
334→    textFiles.push({ name: f.name, path: f.path, folder: folderNames[2] });
335→  }
336→
337→  // Upload root files
338→  for (const tf of textFiles.filter((f) => !f.folder)) {
339→    count(await op(client, `Upload ${tf.name}`, () => uploadFile(client, tf.path, tf.name)));
340→  }
341→  // Upload into docs
342→  count(
343→    await op(client, `Navigate to ${folderNames[0]}`, () => enterFolder(client, folderNames[0]))
344→  );
345→  for (const tf of textFiles.filter((f) => f.folder === folderNames[0])) {
346→    count(await op(client, `Upload ${tf.name}`, () => uploadFile(client, tf.path, tf.name)));
347→  }
348→  count(await op(client, 'Back to root', () => goToRoot(client)));
349→
350→  // Upload into data
351→  count(
352→    await op(client, `Navigate to ${folderNames[2]}`, () => enterFolder(client, folderNames[2]))
353→  );
354→  for (const tf of textFiles.filter((f) => f.folder === folderNames[2])) {
355→    count(await op(client, `Upload ${tf.name}`, () => uploadFile(client, tf.path, tf.name)));
356→  }
357→  count(await op(client, 'Back to root', () => goToRoot(client)));
358→
359→  // ─── Phase 3: Upload medium binary files ─────────────────────────────
360→  console.log(`  [C${id}] Phase 3: Uploading 10 medium binary files (10–50KB)...`);
361→
362→  const mediumFiles: { name: string; path: string }[] = [];
363→  for (let i = 1; i <= 10; i++) {
364→    const sizeKb = 10 + Math.floor(Math.random() * 40); // 10-50KB
365→    const f = createTestBinaryFile(sizeKb, `${prefix}-medium-${i}.bin`);
366→    mediumFiles.push({ name: f.name, path: f.path });
367→  }
368→
369→  // Upload half to root, half to images folder
370→  for (const mf of mediumFiles.slice(0, 5)) {
371→    count(await op(client, `Upload ${mf.name}`, () => uploadFile(client, mf.path, mf.name)));
372→  }
373→  count(
374→    await op(client, `Navigate to ${folderNames[1]}`, () => enterFolder(client, folderNames[1]))
375→  );
376→  for (const mf of mediumFiles.slice(5)) {
377→    count(await op(client, `Upload ${mf.name}`, () => uploadFile(client, mf.path, mf.name)));
378→  }
379→  count(await op(client, 'Back to root', () => goToRoot(client)));
380→
381→  // ─── Phase 4: Upload large binary files ──────────────────────────────
382→  console.log(`  [C${id}] Phase 4: Uploading 5 large binary files (100–500KB)...`);
383→
384→  const largeFiles: { name: string; path: string }[] = [];
385→  const largeSizes = [100, 200, 300, 400, 500];
386→  for (let i = 0; i < 5; i++) {
387→    const f = createTestBinaryFile(largeSizes[i], `${prefix}-large-${i + 1}.bin`);
388→    largeFiles.push({ name: f.name, path: f.path });
389→  }
390→
391→  for (const lf of largeFiles) {
392→    count(
393→      await op(client, `Upload ${lf.name} (${largeSizes[largeFiles.indexOf(lf)]}KB)`, () =>
394→        uploadFile(client, lf.path, lf.name)
395→      )
396→    );
397→  }
398→
399→  // ─── Phase 5: Re-upload files (overwrite triggers IPNS publish) ─────
400→  // Text editor dialog is unreliable on staging (IPNS resolve for file
401→  // content hangs). Re-uploading with same filename overwrites the file,
402→  // which equally triggers metadata update + IPNS publish.
403→  console.log(`  [C${id}] Phase 5: Re-uploading 5 files (overwrite)...`);
404→
405→  for (let i = 1; i <= 5; i++) {
406→    const f = createTestTextFile(
407→      `${prefix}-note-${i}.txt`,
408→      `EDITED by client ${id} at ${new Date().toISOString()}. Revision ${i}.\n${'Updated content block. '.repeat(30)}`
409→    );
410→    count(await op(client, `Re-upload ${f.name}`, () => uploadFile(client, f.path, f.name)));
411→  }
412→
413→  // ─── Phase 6: Rename items ───────────────────────────────────────────
414→  console.log(`  [C${id}] Phase 6: Renaming 8 items...`);
415→
416→  // Rename 5 root files
417→  for (let i = 1; i <= 5; i++) {
418→    const oldName = `${prefix}-note-${i}.txt`;
419→    const newName = `${prefix}-renamed-note-${i}.txt`;
420→    count(
421→      await op(client, `Rename ${oldName} → ${newName}`, () => renameItem(client, oldName, newName))
422→    );
423→  }
424→
425→  // Rename 2 folders
426→  count(
427→    await op(client, `Rename folder ${folderNames[4]}`, () =>
428→      renameItem(client, folderNames[4], `${prefix}-renamed-temp`)
429→    )
430→  );
431→  count(
432→    await op(client, `Rename folder ${folderNames[3]}`, () =>
433→      renameItem(client, folderNames[3], `${prefix}-renamed-archive`)
434→    )
435→  );
436→
437→  // Rename a large file
438→  count(
439→    await op(client, `Rename ${largeFiles[0].name}`, () =>
440→      renameItem(client, largeFiles[0].name, `${prefix}-renamed-large.bin`)
441→    )
442→  );
443→
444→  // ─── Phase 7: Move items between folders ─────────────────────────────
445→  console.log(`  [C${id}] Phase 7: Moving 6 items individually...`);
446→
447→  // Move renamed notes into docs folder
448→  for (let i = 1; i <= 3; i++) {
449→    const fileName = `${prefix}-renamed-note-${i}.txt`;
450→    count(
451→      await op(client, `Move ${fileName} → ${folderNames[0]}`, () =>
452→        moveItem(client, fileName, folderNames[0])
453→      )
454→    );
455→  }
456→
457→  // Move medium files into renamed-archive
458→  for (let i = 1; i <= 3; i++) {
459→    const fileName = mediumFiles[i - 1].name;
460→    count(
461→      await op(client, `Move ${fileName} → ${prefix}-renamed-archive`, () =>
462→        moveItem(client, fileName, `${prefix}-renamed-archive`)
463→      )
464→    );
465→  }
466→
467→  // ─── Phase 8: Batch move ─────────────────────────────────────────────
468→  console.log(`  [C${id}] Phase 8: Batch moving files...`);
469→
470→  // Batch move remaining medium root files into renamed-temp
471→  const remainingMedium = mediumFiles.slice(3, 5).map((f) => f.name);
472→  if (remainingMedium.length >= 2) {
473→    count(
474→      await op(client, `Batch move ${remainingMedium.length} files → ${prefix}-renamed-temp`, () =>
475→        batchMove(client, remainingMedium, `${prefix}-renamed-temp`)
476→      )
477→    );
478→  }
479→
480→  // Batch move large files (2-4) into data folder
481→  const largesToMove = largeFiles.slice(1, 4).map((f) => f.name);
482→  if (largesToMove.length >= 2) {
483→    count(
484→      await op(client, `Batch move ${largesToMove.length} large files → ${folderNames[2]}`, () =>
485→        batchMove(client, largesToMove, folderNames[2])
486→      )
487→    );
488→  }
489→
490→  // ─── Phase 9: Batch delete ───────────────────────────────────────────
491→  console.log(`  [C${id}] Phase 9: Batch deleting files...`);
492→
493→  // Navigate to renamed-archive and batch delete the 3 medium files we moved there
494→  count(
495→    await op(client, `Navigate to ${prefix}-renamed-archive`, () =>
496→      enterFolder(client, `${prefix}-renamed-archive`)
497→    )
498→  );
499→  const archiveFiles = mediumFiles.slice(0, 3).map((f) => f.name);
500→  if (archiveFiles.length >= 2) {
501→    count(
502→      await op(client, `Batch delete ${archiveFiles.length} files from archive`, () =>
503→        batchDelete(client, archiveFiles)
504→      )
505→    );
506→  }
507→  count(await op(client, 'Back to root', () => goToRoot(client)));
508→
509→  // Navigate to data folder and batch delete log files
510→  count(
511→    await op(client, `Navigate to ${folderNames[2]}`, () => enterFolder(client, folderNames[2]))
512→  );
513→  const dataLogFiles = [`${prefix}-log-1.txt`, `${prefix}-log-2.txt`, `${prefix}-log-3.txt`];
514→  count(
515→    await op(client, `Batch delete ${dataLogFiles.length} log files`, () =>
516→      batchDelete(client, dataLogFiles)
517→    )
518→  );
519→  count(await op(client, 'Back to root', () => goToRoot(client)));
520→
521→  // ─── Phase 10: Individual cleanup deletes ────────────────────────────
522→  console.log(`  [C${id}] Phase 10: Cleaning up remaining items...`);
523→
524→  // Delete remaining root items one by one
525→  const rootCleanup = [
526→    `${prefix}-renamed-note-4.txt`,
527→    `${prefix}-renamed-note-5.txt`,
528→    `${prefix}-renamed-large.bin`,
